param([Parameter(Mandatory = $true)][string]$P)
# The same screen set for the 0.4.2 baseline and the 0.5.0 run (windowed 1600x900): title, settings, library, load panel,
# daily-life map + status tabs (slot 001), story (slot 002). Dumps land in harness/out as <P>_<screen>.txt.
$rb = Join-Path $PSScriptRoot 'run_batch.ps1'
function B([string]$name, [string]$cmds, [int]$t = 120) { & powershell -NoProfile -ExecutionPolicy Bypass -File $rb -Name $name -Commands $cmds -TimeoutSec $t | Select-String -Pattern 'cjkscan|ERR|done|TIMEOUT|NOT RUNNING|detect' }
B "${P}_title" "res 1600 900;;wait 4;;detect;;dump ${P}_title;;cjkscan ${P}_title;;show /UI/Layer_3/SystemSettingPanel 1;;wait 2;;res 1600 900;;wait 2;;dump ${P}_settings;;cjkscan ${P}_settings;;show /UI/Layer_3/SystemSettingPanel 0;;wait 1;;show /UI/Layer_3/LibraryPanel 1;;wait 2;;dump ${P}_library;;cjkscan ${P}_library;;show /UI/Layer_3/LibraryPanel 0;;wait 1;;show /UI/Layer_2/LoadGamePanel 1;;wait 2;;dump ${P}_load;;cjkscan ${P}_load;;show /UI/Layer_2/LoadGamePanel 0;;wait 1"
B "${P}_free" "loadsave 001;;wait 18;;res 1600 900;;wait 2;;dump ${P}_free;;cjkscan ${P}_free;;click /[UI]/MainUI/Layer_1/MenuButton/ToggleButton_Status_2;;wait 3;;dump ${P}_status_first;;cjkscan ${P}_status_first;;mouseclick /[UI]/TopPanel/StatusPanel/Container/Buttons/LeftButtons/StatusButton_Social;;wait 2;;dump ${P}_status_social;;cjkscan ${P}_status_social;;mouseclick /[UI]/TopPanel/StatusPanel/Container/Buttons/LeftButtons/StatusButton_Item;;wait 2;;dump ${P}_status_item;;cjkscan ${P}_status_item;;mouseclick /[UI]/TopPanel/StatusPanel/Container/Buttons/LeftButtons/StatusButton_Property;;wait 2;;dump ${P}_status_property;;cjkscan ${P}_status_property;;mouseclick /[UI]/TopPanel/StatusPanel/Container/Buttons/LeftButtons/StatusButton_Legend;;wait 2;;dump ${P}_status_legend;;cjkscan ${P}_status_legend" 180
B "${P}_story" "loadsave 002;;wait 18;;res 1600 900;;wait 3;;dump ${P}_story0;;cjkscan ${P}_story0;;textstat" 180
